  authoredPython: {"685":"class UnionFind:\n    def __init__(self, n):\n        self.parent = list(range(n))\n        self.size = [1] * n\n        self.count = n\n\n    def find(self, node):\n        while self.parent[node] != node:\n            self.parent[node] = self.parent[self.parent[node]]\n            node = self.parent[node]\n        return node\n\n    def union(self, first, second):\n        first, second = self.find(first), self.find(second)\n        if first == second:\n            return False\n        if self.size[first] < self.size[second]:\n            first, second = second, first\n        self.parent[second] = first\n        self.size[first] += self.size[second]\n        self.count -= 1\n        return True\n\ndef findRedundantDirectedConnection(edges):\n    incoming, earlier, later = {}, -1, -1\n    for index, (parent, child) in enumerate(edges):\n        if child in incoming:\n            earlier, later = incoming[child], index\n        else:\n            incoming[child] = index\n    dsu, cycle = UnionFind(len(edges)), -1\n    for index, (parent, child) in enumerate(edges):\n        if index == later:\n            continue\n        if not dsu.union(parent - 1, child - 1):  # step: scan\n            cycle = index\n            break\n    chosen = later if cycle < 0 else earlier if earlier >= 0 else cycle  # step: choose\n    return edges[chosen]  # step: return","827":"class UnionFind:\n    def __init__(self, n):\n        self.parent = list(range(n))\n        self.size = [1] * n\n        self.count = n\n\n    def find(self, node):\n        while self.parent[node] != node:\n            self.parent[node] = self.parent[self.parent[node]]\n            node = self.parent[node]\n        return node\n\n    def union(self, first, second):\n        first, second = self.find(first), self.find(second)\n        if first == second:\n            return False\n        if self.size[first] < self.size[second]:\n            first, second = second, first\n        self.parent[second] = first\n        self.size[first] += self.size[second]\n        self.count -= 1\n        return True\n\ndef largestIsland(grid):\n    n = len(grid)\n    dsu = UnionFind(n * n)\n    for row in range(n):\n        for col in range(n):\n            if grid[row][col]:\n                if row and grid[row - 1][col]:\n                    dsu.union(row * n + col, (row - 1) * n + col)\n                if col and grid[row][col - 1]:\n                    dsu.union(row * n + col, row * n + col - 1)\n    best = 0\n    for row in range(n):\n        for col in range(n):\n            if grid[row][col]:\n                best = max(best, dsu.size[dsu.find(row * n + col)])\n                continue\n            roots = set()\n            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n                nr, nc = row + dr, col + dc\n                if 0 <= nr < n and 0 <= nc < n and grid[nr][nc]:\n                    roots.add(dsu.find(nr * n + nc))\n            best = max(best, 1 + sum(dsu.size[root] for root in roots))  # step: flip\n    return best  # step: return","959":"class UnionFind:\n    def __init__(self, n):\n        self.parent = list(range(n))\n        self.size = [1] * n\n        self.count = n\n\n    def find(self, node):\n        while self.parent[node] != node:\n            self.parent[node] = self.parent[self.parent[node]]\n            node = self.parent[node]\n        return node\n\n    def union(self, first, second):\n        first, second = self.find(first), self.find(second)\n        if first == second:\n            return False\n        if self.size[first] < self.size[second]:\n            first, second = second, first\n        self.parent[second] = first\n        self.size[first] += self.size[second]\n        self.count -= 1\n        return True\n\ndef regionsBySlashes(grid):\n    n = len(grid)\n    dsu = UnionFind(4 * n * n)\n    for row in range(n):\n        for col in range(n):\n            base = 4 * (row * n + col)\n            if grid[row][col] != '/':\n                dsu.union(base, base + 1)\n                dsu.union(base + 2, base + 3)\n            if grid[row][col] != chr(92):\n                dsu.union(base, base + 3)\n                dsu.union(base + 1, base + 2)\n            if row + 1 < n:\n                dsu.union(base + 2, base + 4 * n)\n            if col + 1 < n:\n                dsu.union(base + 1, base + 7)\n            # step: cell\n    return dsu.count  # step: return","1168":"class UnionFind:\n    def __init__(self, n):\n        self.parent = list(range(n))\n        self.size = [1] * n\n        self.count = n\n\n    def find(self, node):\n        while self.parent[node] != node:\n            self.parent[node] = self.parent[self.parent[node]]\n            node = self.parent[node]\n        return node\n\n    def union(self, first, second):\n        first, second = self.find(first), self.find(second)\n        if first == second:\n            return False\n        if self.size[first] < self.size[second]:\n            first, second = second, first\n        self.parent[second] = first\n        self.size[first] += self.size[second]\n        self.count -= 1\n        return True\n\ndef minCostToSupplyWater(n, wells, pipes):\n    edges = [(0, house + 1, cost) for house, cost in enumerate(wells)] + [tuple(edge) for edge in pipes]\n    edges.sort(key=lambda edge: edge[2])\n    dsu, total = UnionFind(n + 1), 0\n    for first, second, cost in edges:\n        if dsu.union(first, second):  # step: edge\n            total += cost\n        if dsu.count == 1:\n            break\n    return total  # step: return"},
